const crossPlatform = ["linux", "macos", "windows"];
const unixAndBsd = ["linux", "macos", "bsd"];

function app(slug, name, summary, repositoryUrl, categories, options = {}) {
  return [
    slug,
    {
      name,
      summary,
      repository_url: repositoryUrl,
      primary_type: "cli",
      categories,
      platforms: unix,
      install_methods: ["brew", "binary"],
      source_model: "open_source",
      pricing_model: "free",
      ...options,
    },
  ];
}

